  result: z.object({
    agents: z.array(
      z.object({
        pane_id: z.string(),
        agent: z.string(),
        agent_session: z.object({ kind: z.string(), value: z.string() }).optional(),
      }),
    ),
  }),
});

function parseAsks(rest: string[]): Ask[] {
  return Array.from({ length: rest.length / 3 }, (_: unknown, i: number): Ask => ({
    pane: rest[i * 3],
    file: rest[i * 3 + 1],
    message: rest[i * 3 + 2],
  }));
}

